import{_ as s,O as o,H as i,f as h,i as l,k as r,b as t,j as a}from"./chunks/framework.Ch3ZxHbh.js";const b=JSON.parse(`{"title":"The home office employee's best companion","description":"","frontmatter":{},"headers":[],"relativePath":"blog/home-office-pet.md","filePath":"blog/home-office-pet.md"}`),d={name:"blog/home-office-pet.md"};function m(c,e,p,f,u,g){const n=o("SeriesChart");return i(),h("div",null,[e[0]||(e[0]=l('<h1 id="the-home-office-employee-s-best-companion" tabindex="-1">The home office employee&#39;s best companion <a class="header-anchor" href="#the-home-office-employee-s-best-companion" aria-label="Permalink to &quot;The home office employee&#39;s best companion&quot;">​</a></h1><div class="byline"><span class="byline-author">Alexander Götz</span><span class="byline-date">8 January 2021</span></div><p>Consumption can satisfy many needs. But what about feelings of loneliness? The pandemic calls for reduced mobility and a retreat into one&#39;s own four walls, where home offices are less crowded. Figures from animal shelters document an increased interest in acquiring pets. The free newspaper 20 Minuten reported from a survey of some animal shelters that demand for dogs and cats rose sharply during the pandemic (<a href="https://www.20min.ch/story/die-leute-kompensierten-mit-einem-neuen-buesi-oder-hund-ihre-einsamkeit-332588381409" target="_blank" rel="noreferrer">20 Minuten</a>). At the beginning of 2021, the NZZ confirmed this with registration figures from animal databases (<a href="https://www.nzz.ch/schweiz/haustiere-boomen-waehrend-der-corona-pandemie-ld.1594752" target="_blank" rel="noreferrer">NZZ</a>). According to the article, the home-office recommendation is the cause of this higher demand.</p><p>Internet search queries allow a more differentiated look at the developments. Over the last five years, interest in the keywords <em>tierheim</em> (animal shelter), <em>qualipet</em> (a Swiss pet retailer) and <em>meerschweinchen</em> (guinea pig) clearly increased. March 2020 produced strong peaks for <em>qualipet</em> and <em>meerschweinchen</em>. This could indicate that the Swiss preferred pet shops over animal shelters, which makes sense, since the shelters had to close under the Covid-19 measures and could only serve the rising demand at the very start of the lockdown.</p>',4)),r(n,{src:"https://cdn.jsdelivr.net/gh/trendecon/media-content@master/data_examples/article_9.csv",ids:["qualipet","tierheim","meerschweinchen"],roller:8,title:"Pet-related searches",subtitle:"8-week rolling average"}),e[1]||(e[1]=t("p",null,[a("The NZZ reports concrete figures from the animal databases Amicus and Identitas. According to their numbers, the upward trend in animal registrations also showed a disproportionate jump in 2020. The trendEcon data below indicates that small animals such as guinea pigs were in particularly high demand during the first phase of the lockdown. The keywords "),t("em",null,"hund kaufen"),a(" (buy dog) and "),t("em",null,"katze kaufen"),a(" (buy cat) also became more popular, though less so than "),t("em",null,"meerschweinchen"),a(". After a short drop in the summer, searches for all pets rebounded, with cats enjoying the greatest popularity.")],-1)),r(n,{src:"https://cdn.jsdelivr.net/gh/trendecon/media-content@master/data_examples/article_9.csv",ids:["hund kaufen","katze kaufen","meerschweinchen"],roller:4,from:"2020-01-01",covid:!0,title:"Buying a pet in 2020",subtitle:"4-week rolling average; dashed lines mark Swiss Covid-19 phases"}),e[2]||(e[2]=t("p",null,"How far pets are part of the new standard of living remains uncertain. Depending on federal and cantonal guidelines, the desire for a home-office dog could endure. If normality returns through vaccination, keeping a pet may become cumbersome and some employees might return their animals to the shelters. That, too, depends on whether home offices stay after the pandemic.",-1))])}const y=s(d,[["render",m]]);export{b as __pageData,y as default};
